17	impl Eval for ast::Code<'_> {
18	    type Output = Value;
19	
20	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
21	        eval_code(vm, &mut self.exprs())
22	    }
23	}
24	
25	/// Evaluate a stream of expressions.
26	fn eval_code<'a>(
27	    vm: &mut Vm,
28	    exprs: &mut impl Iterator<Item = ast::Expr<'a>>,
29	) -> SourceResult<Value> {
30	    let flow = vm.flow.take();
31	    let mut output = Value::None;
32	
33	    while let Some(expr) = exprs.next() {
34	        let span = expr.span();
35	        let value = match expr {
36	            ast::Expr::SetRule(set) => {
37	                let styles = set.eval(vm)?;
38	                if vm.flow.is_some() {
39	                    break;
40	                }
41	
42	                let tail = eval_code(vm, exprs)?.display();
43	                Value::Content(tail.styled_with_map(styles))
44	            }
45	            ast::Expr::ShowRule(show) => {
46	                let recipe = show.eval(vm)?;
47	                if vm.flow.is_some() {
48	                    break;
49	                }
50	
51	                let tail = eval_code(vm, exprs)?.display();
52	                Value::Content(tail.styled_with_recipe(
53	                    &mut vm.engine,
54	                    vm.context,
55	                    recipe,
56	                )?)
57	            }
58	            _ => expr.eval(vm)?,
59	        };
60	
61	        output = ops::join(output, value).at(span)?;
62	
63	        if let Some(event) = &vm.flow {
64	            warn_for_discarded_content(&mut vm.engine, event, &output);
65	            break;
66	        }
67	    }
68	
69	    if flow.is_some() {
70	        vm.flow = flow;
71	    }
72	
73	    Ok(output)
74	}
75	
76	impl Eval for ast::Expr<'_> {
77	    type Output = Value;
78	
79	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
80	        let span = self.span();
81	        let forbidden = |name| {
82	            error!(span, "{name} is only allowed directly in code and content blocks")
83	        };
84	
85	        let value = match self {
86	            Self::Text(v) => v.eval(vm).map(Value::Content),
87	            Self::Space(v) => v.eval(vm).map(Value::Content),
88	            Self::Linebreak(v) => v.eval(vm).map(Value::Content),
89	            Self::Parbreak(v) => v.eval(vm).map(Value::Content),
90	            Self::Escape(v) => v.eval(vm),
91	            Self::Shorthand(v) => v.eval(vm),
92	            Self::SmartQuote(v) => v.eval(vm).map(Value::Content),
93	            Self::Strong(v) => v.eval(vm).map(Value::Content),
94	            Self::Emph(v) => v.eval(vm).map(Value::Content),
95	            Self::Raw(v) => v.eval(vm).map(Value::Content),
96	            Self::Link(v) => v.eval(vm).map(Value::Content),
97	            Self::Label(v) => v.eval(vm),
98	            Self::Ref(v) => v.eval(vm).map(Value::Content),
99	            Self::Heading(v) => v.eval(vm).map(Value::Content),
100	            Self::ListItem(v) => v.eval(vm).map(Value::Content),
101	            Self::EnumItem(v) => v.eval(vm).map(Value::Content),
102	            Self::TermItem(v) => v.eval(vm).map(Value::Content),
103	            Self::Equation(v) => v.eval(vm).map(Value::Content),
104	            Self::Math(v) => v.eval(vm).map(Value::Content),
105	            Self::MathLetter(v) => v.eval(vm).map(Value::Content),
106	            Self::MathSymbol(v) => v.eval(vm).map(Value::Content),
107	            Self::MathNumber(v) => v.eval(vm).map(Value::Content),
108	            Self::MathIdent(v) => v.eval(vm),
109	            Self::MathFieldAccess(v) => v.eval(vm),
110	            Self::MathShorthand(v) => v.eval(vm),
111	            Self::MathAlignPoint(v) => v.eval(vm).map(Value::Content),
112	            Self::MathCall(v) => v.eval(vm),
113	            Self::MathOpening(v) => v.eval(vm).map(Value::Content),
114	            Self::MathClosing(v) => v.eval(vm).map(Value::Content),
115	            Self::MathDelimited(v) => v.eval(vm).map(Value::Content),
116	            Self::MathAttach(v) => v.eval(vm).map(Value::Content),
117	            Self::MathPrimes(v) => v.eval(vm).map(Value::Content),
118	            Self::MathFrac(v) => v.eval(vm).map(Value::Content),
119	            Self::MathRoot(v) => v.eval(vm).map(Value::Content),
120	            Self::Ident(v) => v.eval(vm),
121	            Self::None(v) => v.eval(vm),
122	            Self::Auto(v) => v.eval(vm),
123	            Self::Bool(v) => v.eval(vm),
124	            Self::Int(v) => v.eval(vm),
125	            Self::Float(v) => v.eval(vm),
126	            Self::Numeric(v) => v.eval(vm),
127	            Self::Str(v) => v.eval(vm),
128	            Self::CodeBlock(v) => v.eval(vm),
129	            Self::ContentBlock(v) => v.eval(vm).map(Value::Content),
130	            Self::Array(v) => v.eval(vm).map(Value::Array),
131	            Self::Dict(v) => v.eval(vm).map(Value::Dict),
132	            Self::Parenthesized(v) => v.eval(vm),
133	            Self::FieldAccess(v) => v.eval(vm),
134	            Self::FuncCall(v) => v.eval(vm),
135	            Self::Closure(v) => v.eval(vm),
136	            Self::Unary(v) => v.eval(vm),
137	            Self::Binary(v) => v.eval(vm),
138	            Self::LetBinding(v) => v.eval(vm),
139	            Self::DestructAssignment(v) => v.eval(vm),
140	            Self::SetRule(_) => bail!(forbidden("set")),
141	            Self::ShowRule(_) => bail!(forbidden("show")),
142	            Self::Contextual(v) => v.eval(vm).map(Value::Content),
143	            Self::Conditional(v) => v.eval(vm),
144	            Self::WhileLoop(v) => v.eval(vm),
145	            Self::ForLoop(v) => v.eval(vm),
146	            Self::ModuleImport(v) => v.eval(vm),
147	            Self::ModuleInclude(v) => v.eval(vm).map(Value::Content),
148	            Self::LoopBreak(v) => v.eval(vm),
149	            Self::LoopContinue(v) => v.eval(vm),
150	            Self::FuncReturn(v) => v.eval(vm),
151	        }?
152	        .spanned(span);
153	
154	        // This satisfies the obligation to call `Vm::trace` for almost all
155	        // value-producing expressions!
156	        vm.trace_at(span, &value);
157	
158	        Ok(value)
159	    }
160	}
