230	impl Eval for ast::Array<'_> {
231	    type Output = Array;
232	
233	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
234	        let mut items = self.items();
235	
236	        let mut vec = EcoVec::with_capacity(items.size_hint().0);
237	
238	        // We raise an error when one of the array items is the spread of a
239	        // dictionary. If _all_ of the array items are spreads of dictionaries,
240	        // the user probably wanted to write `(: ..dict_a, ..dict_b)` instead
241	        // to create a dictionary, not an array.
242	        let mut all_dict_spreads = true;
243	
244	        while let Some(item) = items.next() {
245	            match item {
246	                ast::ArrayItem::Pos(expr) => {
247	                    all_dict_spreads = false;
248	                    vec.push(expr.eval(vm)?);
249	                }
250	                ast::ArrayItem::Spread(spread) => match spread.expr().eval(vm)? {
251	                    Value::None => {}
252	                    Value::Array(array) => {
253	                        all_dict_spreads = false;
254	                        vec.extend(array);
255	                    }
256	                    v @ Value::Dict(_)
257	                        if all_dict_spreads
258	                        // Lookahead to see whether remaining items are spreads
259	                        // of dicts
260	                        && items.all(|item| matches!(
261	                            item,
262	                            ast::ArrayItem::Spread(spread) if matches!(
263	                                spread.expr().eval(vm),
264	                                Ok(Value::Dict(_)),
265	                            ),
266	                        )) =>
267	                    {
268	                        let fixed = self.to_untyped().full_text().replacen("(", "(: ", 1);
269	                        bail!(
270	                            spread.span(), "cannot spread {} into array", v.ty();
271	                            hint: "add a colon to create a dictionary instead: `{fixed}`";
272	                        )
273	                    }
274	                    v => bail!(spread.span(), "cannot spread {} into array", v.ty()),
275	                },
276	            }
277	        }
278	
279	        Ok(vec.into())
280	    }
281	}
