1	use comemo::Tracked;
2	use ecow::eco_format;
3	use typst_library::World;
4	use typst_library::diag::{HintedString, warning};
5	use typst_library::engine::Engine;
6	use typst_library::foundations::{
7	    Binding, Context, IntoValue, Scopes, Value, WorldBindingExt,
8	};
9	use typst_syntax::Span;
10	use typst_syntax::ast::{self, AstNode};
11	
12	use crate::FlowEvent;
13	
14	/// A virtual machine.
15	///
16	/// Holds the state needed to [evaluate](crate::eval()) Typst sources. A
17	/// new virtual machine is created for each module evaluation and function call.
18	pub struct Vm<'a> {
19	    /// The underlying virtual typesetter.
20	    pub engine: Engine<'a>,
21	    /// A control flow event that is currently happening.
22	    pub flow: Option<FlowEvent>,
23	    /// The stack of scopes.
24	    pub scopes: Scopes<'a>,
25	    /// A span that is currently under inspection. If this is `Some`, we're in
26	    /// tracing mode, and will record every value the given span sees.
27	    pub inspected: Option<Span>,
28	    /// Data that is contextually made accessible to code behind the scenes.
29	    pub context: Tracked<'a, Context<'a>>,
30	}
31	
32	impl<'a> Vm<'a> {
33	    /// Create a new virtual machine.
34	    pub fn new(
35	        engine: Engine<'a>,
36	        context: Tracked<'a, Context<'a>>,
37	        scopes: Scopes<'a>,
38	        target: Span,
39	    ) -> Self {
40	        let inspected = target.id().and_then(|id| engine.traced.get(id));
41	        Self { engine, context, flow: None, scopes, inspected }
42	    }
43	
44	    /// Access the underlying world.
45	    pub fn world(&self) -> Tracked<'a, dyn World + 'a> {
46	        self.engine.world
47	    }
48	
49	    /// Bind a value to an identifier.
50	    ///
51	    /// This will create a [`Binding`] with the value and the identifier's span.
52	    pub fn define(&mut self, var: ast::Ident, value: impl IntoValue) {
53	        self.bind(var, Binding::new(value, var.span()));
54	    }
55	
56	    /// Insert a binding into the current scope.
57	    ///
58	    /// This will insert the value into the top-most scope and make it available
59	    /// for dynamic tracing, assisting IDE functionality.
60	    pub fn bind(&mut self, var: ast::Ident, binding: Binding) {
61	        if let Ok(value) = binding.read(self.engine.world.silent_binding_guard()) {
62	            self.trace_at(var.span(), value);
63	        }
64	
65	        // This will become an error in the parser if `is` becomes a keyword.
66	        if var.get() == "is" {
67	            self.engine.sink.warn(warning!(
68	                var.span(),
69	                "`is` will likely become a keyword in future versions and will \
70	                not be allowed as an identifier";
71	                hint: "rename this variable to avoid future errors";
72	                hint: "try `is_` instead";
73	            ));
74	        }
75	
76	        self.scopes.top.bind(var.get().clone(), binding);
77	    }
78	
