283	impl Eval for ast::Dict<'_> {
284	    type Output = Dict;
285	
286	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
287	        let mut map = indexmap::IndexMap::default();
288	        let mut invalid_keys = eco_vec![];
289	
290	        for item in self.items() {
291	            match item {
292	                ast::DictItem::Named(named) => {
293	                    map.insert(named.name().get().clone().into(), named.expr().eval(vm)?);
294	                }
295	                ast::DictItem::Keyed(keyed) => {
296	                    let raw_key = keyed.key();
297	                    let key = raw_key.eval(vm)?;
298	                    let key =
299	                        key.cast::<Str>().at(raw_key.span()).unwrap_or_else(|errors| {
300	                            invalid_keys.extend(errors);
301	                            Str::default()
302	                        });
303	                    map.insert(key, keyed.expr().eval(vm)?);
304	                }
305	                ast::DictItem::Spread(spread) => match spread.expr().eval(vm)? {
306	                    Value::None => {}
307	                    Value::Dict(dict) => map.extend(dict),
308	                    v => bail!(spread.span(), "cannot spread {} into dictionary", v.ty()),
309	                },
310	            }
311	        }
312	
313	        if !invalid_keys.is_empty() {
314	            return Err(invalid_keys);
315	        }
316	
317	        Ok(map.into())
318	    }
319	}
