361	/// Access a field on a target value.
362	pub(crate) fn access_field(
363	    vm: &mut Vm,
364	    target: Value,
365	    field: &str,
366	    field_span: Span,
367	) -> SourceResult<Value> {
368	    let err = match target
369	        .field(field, vm.engine.binding_guard(field_span))
370	        .at(field_span)
371	    {
372	        Ok(value) => return Ok(value),
373	        Err(err) => err,
374	    };
375	
376	    // Missing fields may actually be present if they are settable parameters
377	    // on elements accessed with context, e.g. `block.stroke`.
378	    if let Value::Func(func) = &target
379	        && let Some(element) = func.to_element()
380	        && let Some(field_accessor) = element.settable_field_accessor(field)
381	    {
382	        let styles = vm.context.styles().at(field_span)?;
383	        return Ok(field_accessor(styles));
384	    }
385	
386	    Err(err)
387	}
