389	impl Eval for ast::Contextual<'_> {
390	    type Output = Content;
391	
392	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
393	        let body = self.body();
394	
395	        // Collect captured variables.
396	        let captured = {
397	            let mut visitor = CapturesVisitor::new(Some(&vm.scopes), Capturer::Context);
398	            visitor.visit(body.to_untyped());
399	            visitor.finish()
400	        };
401	
402	        // Define the closure.
403	        let closure = Closure {
404	            node: ClosureNode::Context(self.body().to_untyped().clone()),
405	            defaults: vec![],
406	            captured,
407	            num_pos_params: 0,
408	            params_span: Span::detached(),
409	        };
410	
411	        let func = Func::from(closure).spanned(body.span());
412	        Ok(ContextElem::new(func).pack().spanned(body.span()))
413	    }
414	}
