416	/// Emits a warning when we discard content while returning unconditionally.
417	fn warn_for_discarded_content(engine: &mut Engine, event: &FlowEvent, joined: &Value) {
418	    let FlowEvent::Return(span, Some(_), false) = event else { return };
419	    let Value::Content(tree) = &joined else { return };
420	
421	    let selector = singleton!(
422	        Selector,
423	        Selector::Or(eco_vec![State::select_any(), Counter::select_any()])
424	    );
425	
426	    let mut warning = warning!(
427	        *span,
428	        "this return unconditionally discards the content before it";
429	        hint: "try omitting the `return` to automatically join all values";
430	    );
431	
432	    if tree.query_first_naive(selector).is_some() {
433	        warning.hint("state/counter updates are content that must end up in the document to have an effect");
434	    }
435	
436	    engine.sink.warn(warning);
437	}
