439	/// Evaluation error for an integer literal.
440	#[cold]
441	fn int_literal_error(int: ast::Int, err: ast::IntLiteralError) -> SourceDiagnostic {
442	    let span = int.span();
443	    match err {
444	        ast::IntLiteralError::PosOverflow { base, max_plus_one: _ } => {
445	            let mut error = error!(
446	                span,
447	                "integer value is too large";
448	                hint: "value does not fit into a signed 64-bit integer";
449	            );
450	            if base.is_none() {
451	                error.hint(
452	                    "a floating point number could approximately represent this value",
453	                );
454	                error.hint(eco_format!(
455	                    "you can use a floating point number by appending a dot: `{}.`",
456	                    int.to_untyped().leaf_text()
457	                ));
458	            }
459	            error
460	        }
461	        ast::IntLiteralError::InvalidDigit(base, digits) => {
462	            let (range, bad_digits) = find_bad_digits(base, digits);
463	            // Offset by two to skip the leading `0b`/`0o`/`0x`.
464	            let sub_range = SubRange::new(range.start + 2, range.end + 2);
465	            let hint_span = DiagSpan::from_span(span, sub_range);
466	            let the_digits_are_invalid = match *bad_digits {
467	                [digit] => eco_format!("the digit `{digit}` is invalid"),
468	                [first, last] => {
469	                    eco_format!("the digits `{first}` and `{last}` are invalid")
470	                }
471	                [ref digits @ .., last] => {
472	                    eco_format!(
473	                        "the digits {}and `{last}` are invalid",
474	                        digits.iter().fold(
475	                            String::with_capacity(5 * digits.len()),
476	                            |mut buf, digit| {
477	                                let _ = write!(buf, "`{digit}`, ");
478	                                buf
479	                            }
480	                        )
481	                    )
482	                }
483	                [] => unreachable!(),
484	            };
485	            error!(
486	                span,
487	                "integer contains digits that are not valid for a{} {} number",
488	                    if base == ast::NonDecimalBase::Octal { "n" } else { "" },
489	                    base.name();
490	                hint[hint_span]: "{the_digits_are_invalid}";
491	                hint: "{} numbers only allow digits {}",
492	                    base.name(),
493	                    match base {
494	                        ast::NonDecimalBase::Hex => "0-9, a-f, A-F",
495	                        ast::NonDecimalBase::Octal => "0-7",
496	                        ast::NonDecimalBase::Binary => "0-1",
497	                    };
498	            )
499	        }
500	    }
501	}
