503	/// Find invalid digits for a non-decimal integer. Returns the sub-range of the
504	/// digits and a string separated by commas.
505	///
506	/// We only check for digits/letters depending on the base since the lexer
507	/// allows only ASCII digits for binary/octal, but allows ASCII letters for hex.
508	pub fn find_bad_digits(
509	    base: ast::NonDecimalBase,
510	    digits: &str,
511	) -> (Range<usize>, Vec<char>) {
512	    let ranges: &[_] = match base {
513	        ast::NonDecimalBase::Hex => &['g'..='z', 'G'..='Z'],
514	        ast::NonDecimalBase::Octal => &['8'..='9'],
515	        ast::NonDecimalBase::Binary => &['2'..='9'],
516	    };
517	    // Yield at most one copy of each digit.
518	    let iter = ranges.iter().flat_map(|range| {
519	        range.clone().filter_map(|c| digits.find(c).map(|index| (index, c)))
520	    });
521	    let mut start = digits.len();
522	    let mut end = 0;
523	    let mut bad_digits = Vec::new();
524	    for (index, digit) in iter {
525	        start = start.min(index);
526	        end = end.max(index + 1); // Equal to `digit.len_utf8()` since ASCII.
527	        bad_digits.push(digit);
528	    }
529	    (start..end, bad_digits)
530	}
