114	impl Eval for ast::ForLoop<'_> {
115	    type Output = Value;
116	
117	    #[typst_macros::time(name = "for loop", span = self.span())]
118	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
119	        let flow = vm.flow.take();
120	        let mut output = Value::None;
121	
122	        macro_rules! iter {
123	            (for $pat:ident in $iterable:expr) => {{
124	                vm.scopes.enter();
125	
126	                for value in $iterable {
127	                    destructure(vm, $pat, value.into_value())?;
128	
129	                    let body = self.body();
130	                    let value = body.eval(vm)?;
131	                    output = ops::join(output, value).at(body.span())?;
132	
133	                    match vm.flow {
134	                        Some(FlowEvent::Break(_)) => {
135	                            vm.flow = None;
136	                            break;
137	                        }
138	                        Some(FlowEvent::Continue(_)) => vm.flow = None,
139	                        Some(FlowEvent::Return(..)) => break,
140	                        None => {}
141	                    }
142	                }
143	
144	                vm.scopes.exit();
145	            }};
146	        }
147	
148	        let pattern = self.pattern();
149	        let iterable = self.iterable().eval(vm)?;
150	        let iterable_type = iterable.ty();
151	
152	        use ast::Pattern;
153	        match (pattern, iterable) {
154	            (_, Value::Array(array)) => {
155	                // Iterate over values of array.
156	                iter!(for pattern in array);
157	            }
158	            (_, Value::Dict(dict)) => {
159	                // Iterate over key-value pairs of dict.
160	                iter!(for pattern in dict.iter());
161	            }
162	            (Pattern::Normal(_) | Pattern::Placeholder(_), Value::Str(str)) => {
163	                // Iterate over graphemes of string.
164	                iter!(for pattern in str.as_str().graphemes(true));
165	            }
166	            (Pattern::Normal(_) | Pattern::Placeholder(_), Value::Bytes(bytes)) => {
167	                // Iterate over the integers of bytes.
168	                iter!(for pattern in bytes.as_slice());
169	            }
170	            (Pattern::Destructuring(_), Value::Str(_) | Value::Bytes(_)) => {
171	                bail!(pattern.span(), "cannot destructure values of {iterable_type}");
172	            }
173	            _ => {
174	                bail!(self.iterable().span(), "cannot loop over {iterable_type}");
175	            }
176	        }
177	
178	        if flow.is_some() {
179	            vm.flow = flow;
180	        }
181	
182	        // Mark the return as conditional.
183	        if let Some(FlowEvent::Return(_, _, conditional)) = &mut vm.flow {
184	            *conditional = true;
185	        }
186	
187	        Ok(output)
188	    }
189	}
