225	/// Whether the expression always evaluates to the same value.
226	fn is_invariant(expr: &SyntaxNode) -> bool {
227	    match expr.cast() {
228	        Some(ast::Expr::Ident(_)) => false,
229	        Some(ast::Expr::MathIdent(_)) => false,
230	        Some(ast::Expr::FieldAccess(access)) => {
231	            is_invariant(access.target().to_untyped())
232	        }
233	        Some(ast::Expr::FuncCall(call)) => {
234	            is_invariant(call.callee().to_untyped())
235	                && is_invariant(call.args().to_untyped())
236	        }
237	        _ => expr.children().all(is_invariant),
238	    }
239	}
240	
241	/// Whether the expression contains a break or return.
242	fn can_diverge(expr: &SyntaxNode) -> bool {
243	    matches!(expr.kind(), SyntaxKind::Break | SyntaxKind::Return)
244	        || expr.children().any(can_diverge)
245	}
