17	impl Eval for ast::ModuleImport<'_> {
18	    type Output = Value;
19	
20	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
21	        let source_expr = self.source();
22	        let source_span = source_expr.span();
23	
24	        let mut source = source_expr.eval(vm)?;
25	        let mut replaced_source = false;
26	
27	        match &source {
28	            Value::Func(func) => {
29	                if func.scope().is_none() {
30	                    bail!(source_span, "cannot import from user-defined functions");
31	                }
32	            }
33	            Value::Type(_) => {}
34	            Value::Module(_) => {}
35	            Value::Str(path) => {
36	                source = Value::Module(import(&mut vm.engine, path, source_span).trace(
37	                    vm.engine.world,
38	                    || Tracepoint::Import(path.clone().into()),
39	                    self.span(),
40	                )?);
41	                replaced_source = true;
42	            }
43	            v if RootedPath::castable(v) => {
44	                let id = v.clone().cast::<RootedPath>().at(source_span)?.intern();
45	                source =
46	                    Value::Module(import_file(&mut vm.engine, id, source_span).trace(
47	                        vm.engine.world,
48	                        || Tracepoint::Import(id.get().vpath().get_with_slash().into()),
49	                        self.span(),
50	                    )?);
51	                replaced_source = true;
52	            }
53	            v => {
54	                bail!(
55	                    source_span,
56	                    "expected path, module, function, or type, found {}",
57	                    v.ty(),
58	                )
59	            }
60	        }
61	
62	        // If there is a rename, import the source itself under that name.
63	        let new_name = self.new_name();
64	        if let Some(new_name) = new_name {
65	            if let ast::Expr::Ident(ident) = self.source()
66	                && ident.as_str() == new_name.as_str()
67	            {
68	                // Warn on `import x as x`
69	                vm.engine.sink.warn(warning!(
70	                    new_name.span(),
71	                    "unnecessary import rename to same name",
72	                ));
73	            }
74	
75	            // Define renamed module on the scope.
76	            vm.define(new_name, source.clone());
77	        }
78	
79	        let scope = source.scope().unwrap();
80	        match self.imports() {
81	            None => {
82	                if new_name.is_none() {
83	                    match self.bare_name() {
84	                        // Bare dynamic string or path imports are not allowed.
85	                        Ok(name)
86	                            if !replaced_source
87	                                || matches!(source_expr, ast::Expr::Str(_)) =>
88	                        {
89	                            if matches!(source_expr, ast::Expr::Ident(_)) {
90	                                vm.engine.sink.warn(warning!(
91	                                    source_expr.span(),
92	                                    "this import has no effect",
93	                                ));
94	                            }
95	                            vm.scopes.top.bind(name, Binding::new(source, source_span));
96	                        }
97	                        Ok(_) | Err(BareImportError::Dynamic) => bail!(
98	                            source_span, "dynamic import requires an explicit name";
99	                            hint: "you can name the import with `as`";
100	                        ),
101	                        Err(BareImportError::PathInvalid) => bail!(
102	                            source_span, "module name would not be a valid identifier";
103	                            hint: "you can rename the import with `as`";
104	                        ),
105	                        // Bad package spec would have failed the import already.
106	                        Err(BareImportError::PackageInvalid) => unreachable!(),
107	                    }
108	                }
109	            }
110	            Some(ast::Imports::Wildcard) => {
111	                for (var, binding) in scope.iter() {
112	                    // Filter out values that are in feature gated bindings and
113	                    // ignore any deprecation warnings that are emitted.
114	                    if binding.read(vm.engine.world.silent_binding_guard()).is_ok() {
115	                        vm.scopes.top.bind(var.clone(), binding.clone());
116	                    }
117	                }
118	            }
119	            Some(ast::Imports::Items(items)) => {
120	                let mut errors = eco_vec![];
121	                for item in items.iter() {
122	                    let mut path = item.path().iter().peekable();
123	                    let mut scope = scope;
124	
125	                    while let Some(component) = &path.next() {
126	                        let field = component.as_str();
127	                        let Some(binding) = scope.get(field) else {
128	                            errors.push(error!(component.span(), "unresolved import"));
129	                            break;
130	                        };
131	
132	                        let value = binding
133	                            .read(vm.engine.binding_guard(component.span()))
134	                            .or_cannot(format_args!("import `{field}`"))
135	                            .at(component.span())?;
136	
137	                        if path.peek().is_some() {
138	                            // Nested import, as this is not the last component.
139	                            // This must be a submodule.
140	                            let Some(submodule) = value.scope() else {
141	                                let error = if matches!(value, Value::Func(function) if function.scope().is_none())
142	                                {
143	                                    error!(
144	                                        component.span(),
145	                                        "cannot import from user-defined functions",
146	                                    )
147	                                } else if !matches!(
148	                                    value,
149	                                    Value::Func(_) | Value::Module(_) | Value::Type(_)
150	                                ) {
151	                                    error!(
152	                                        component.span(),
153	                                        "expected module, function, or type, found {}",
154	                                        value.ty(),
155	                                    )
156	                                } else {
157	                                    panic!("unexpected nested import failure")
158	                                };
159	                                errors.push(error);
160	                                break;
161	                            };
162	
163	                            // Walk into the submodule.
164	                            scope = submodule;
165	                        } else {
166	                            // Now that we have the scope of the innermost submodule
167	                            // in the import path, we may extract the desired item from
168	                            // it.
169	
170	                            // Warn on `import ...: x as x`
171	                            if let ast::ImportItem::Renamed(renamed_item) = &item
172	                                && renamed_item.original_name().as_str()
173	                                    == renamed_item.new_name().as_str()
174	                            {
175	                                vm.engine.sink.warn(warning!(
176	                                    renamed_item.new_name().span(),
177	                                    "unnecessary import rename to same name",
178	                                ));
179	                            }
180	
181	                            vm.bind(item.bound_name(), binding.clone());
182	                        }
183	                    }
184	                }
185	                if !errors.is_empty() {
186	                    return Err(errors);
187	                }
188	            }
189	        }
190	
191	        Ok(Value::None)
192	    }
193	}
