195	impl Eval for ast::ModuleInclude<'_> {
196	    type Output = Content;
197	
198	    fn eval(self, vm: &mut Vm) -> SourceResult<Self::Output> {
199	        let source_span = self.source().span();
200	        let source = self.source().eval(vm)?;
201	        let module = match source {
202	            Value::Str(path) => import(&mut vm.engine, &path, source_span).trace(
203	                vm.engine.world,
204	                || Tracepoint::Include(path.clone().into()),
205	                self.span(),
206	            )?,
207	            Value::Module(module) => module,
208	            v if RootedPath::castable(&v) => {
209	                let id = v.cast::<RootedPath>().at(source_span)?.intern();
210	                import_file(&mut vm.engine, id, source_span).trace(
211	                    vm.engine.world,
212	                    || Tracepoint::Include(id.get().vpath().get_with_slash().into()),
213	                    self.span(),
214	                )?
215	            }
216	            v => bail!(source_span, "expected path or module, found {}", v.ty()),
217	        };
218	        Ok(module.content())
219	    }
220	}
