222	/// Process an import of a package or file relative to the current location.
223	pub fn import(engine: &mut Engine, from: &str, span: Span) -> SourceResult<Module> {
224	    if from.starts_with('@') {
225	        let spec = from.parse::<PackageSpec>().at(span)?;
226	        import_package(engine, spec, span)
227	    } else {
228	        let path = PathOrStr::Str(from.into())
229	            .resolve_if_some(span.id())
230	            .at(span)?
231	            .intern();
232	        import_file(engine, path, span)
233	    }
234	}
235	
236	/// Import a file from a path. The path is resolved relative to the given
237	/// `span`.
238	fn import_file(engine: &mut Engine, id: FileId, span: Span) -> SourceResult<Module> {
239	    // Load the source file.
240	    let source = engine.world.source(id).at(span)?;
241	
242	    // Prevent cyclic importing.
243	    if engine.route.contains(source.id()) {
244	        bail!(span, "cyclic import");
245	    }
246	
247	    // Evaluate the file.
248	    eval(
249	        engine.world,
250	        engine.library,
251	        engine.traced,
252	        TrackedMut::reborrow_mut(&mut engine.sink),
253	        engine.route.track(),
254	        &source,
255	    )
256	}
257	
258	/// Import an external package.
259	fn import_package(
260	    engine: &mut Engine,
261	    spec: PackageSpec,
262	    span: Span,
263	) -> SourceResult<Module> {
264	    let (name, id) = resolve_package(engine, spec, span)?;
265	    import_file(engine, id, span).map(|module| module.with_name(name))
266	}
267	
268	/// Resolve the name and entrypoint of a package.
269	fn resolve_package(
270	    engine: &mut Engine,
271	    spec: PackageSpec,
272	    span: Span,
273	) -> SourceResult<(EcoString, FileId)> {
274	    // Evaluate the manifest.
275	    let manifest_id = RootedPath::new(
276	        VirtualRoot::Package(spec.clone()),
277	        VirtualPath::new("typst.toml").unwrap(),
278	    )
279	    .intern();
280	    let bytes = engine.world.file(manifest_id).at(span)?;
281	    let string = bytes.as_str().map_err(FileError::from).at(span)?;
282	    let manifest: PackageManifest = toml::from_str(string)
283	        .map_err(|err| eco_format!("package manifest is malformed ({})", err.message()))
284	        .at(span)?;
285	    manifest.validate(&spec).at(span)?;
286	
287	    // Evaluate the entry point.
288	    Ok((
289	        manifest.package.name,
290	        RootedPath::new(manifest_id.root().clone(), manifest.package.entrypoint).intern(),
291	    ))
292	}
