98	/// Provide a hint if the callee is a shadowed standard library function.
99	pub fn hint_if_shadowed_std(
100	    vm: &mut Vm,
101	    callee: &ast::Expr,
102	    mut err: HintedString,
103	) -> HintedString {
104	    if let ast::Expr::Ident(ident) = callee {
105	        let ident = ident.get();
106	        if vm.scopes.check_std_shadowed(ident) {
107	            err.hint(eco_format!(
108	                "use `std.{ident}` to access the shadowed standard library function",
109	            ));
110	        }
111	    }
112	    err
113	}
